UPDATE blog_posts SET slug = 'what-keeps-a-student-learning', translations = '{"en":{"title":"What keeps a student learning?","excerpt":"School access is rarely about one barrier. Supplies, tuition support, safe classrooms, trained teachers, and encouragement all help students keep moving forward.","body":"For many families, a uniform, notebook, tuition payment, or long trip to school can place learning out of reach.\n\nShareHope works alongside local educators and families to understand what students need in their own context. That can mean school supplies, scholarship support, safer learning spaces, teacher training, or a trusted mentor.\n\nThe goal is not simply attendance. Consistent access to education gives students structure, confidence, community, and more freedom to shape their own futures.","imageAlt":"Students learning together in a bright classroom","buttonText":"Read more","authorName":"ShareHope Editorial Team","seoTitle":"What keeps a student learning? | ShareHope","seoDescription":"Learn how practical, community-guided support helps students remain connected to education.","tags":["Education","School Access"]}}'::jsonb, updated_at = NOW() WHERE slug = 'classroom-that-changed-everything';

UPDATE blog_posts SET slug = 'health-starts-close-to-home', translations = '{"en":{"title":"Health starts close to home","excerpt":"Mobile clinics, clean water systems, nutrition support, and practical health education work best when communities help shape how care is delivered.","body":"Healthcare can be difficult to reach when the nearest clinic is hours—or even days—away. Reliable water, preventive care, and nutrition support therefore become essential parts of a community’s health system.\n\nShareHope partners with local providers and leaders on mobile clinics, maternal care, water-well maintenance, filtration, hygiene education, and nutrition programs.\n\nThis locally guided approach helps practical resources fit daily life and strengthens the systems communities already trust.","imageAlt":"A clean-water source serving a rural community","buttonText":"Read more","authorName":"ShareHope Health Team","seoTitle":"Health starts close to home | ShareHope","seoDescription":"See how locally guided health, water, and nutrition programs strengthen communities.","tags":["Health","Clean Water"]}}'::jsonb, updated_at = NOW() WHERE slug = 'clean-water-boulsa';

UPDATE blog_posts SET slug = 'why-local-mentors-matter', translations = '{"en":{"title":"Why local mentors matter","excerpt":"Mentorship connects education, work, and leadership by giving young people consistent guidance from someone who understands their community.","body":"Resources can open a door, but trusted relationships often help a young person walk through it. Local mentors understand the pressures students and young adults face.\n\nShareHope’s community-development work supports mentorship networks alongside vocational training, family support, and entrepreneurship.\n\nA strong mentorship network lasts beyond any single project: today’s participant can become tomorrow’s guide, employer, or community leader.","imageAlt":"A local mentor speaking with a student","buttonText":"Read more","authorName":"ShareHope Community Team","seoTitle":"Why local mentors matter | ShareHope","seoDescription":"Learn how trusted local mentors connect education, opportunity, and leadership.","tags":["Community","Mentorship"]}}'::jsonb, updated_at = NOW() WHERE slug = 'mentors-shaping-tomorrow';

UPDATE blog_posts SET slug = 'what-community-led-means', translations = '{"en":{"title":"What community-led really means","excerpt":"It begins with a simple discipline: arrive with questions, listen to local priorities, and build around the knowledge already present.","body":"Community-led is more than a phrase. It changes who defines the problem, who chooses the response, and who owns the result.\n\nLocal leaders help identify priorities, shape program delivery, and explain what progress should look like.\n\nListening first takes patience, but it produces programs that are more relevant, more trusted, and more likely to last.","imageAlt":"Community partners planning a local program together","buttonText":"Read more","authorName":"ShareHope Field Team","seoTitle":"What community-led really means | ShareHope","seoDescription":"Explore how listening and local leadership shape every ShareHope program.","tags":["Field Notes","Local Leadership"]}}'::jsonb, updated_at = NOW() WHERE slug = 'mobile-clinic-week';

UPDATE blog_posts SET slug = 'small-barriers-big-difference', translations = '{"en":{"title":"Small barriers can make a big difference","excerpt":"A notebook, uniform, transportation cost, or tuition fee can determine whether a child is able to stay connected to school.","body":"Educational opportunity is shaped by practical details. When a family must choose between essential household needs and the cost of school, even a modest expense can interrupt learning.\n\nShareHope’s education work combines direct student support with investment in teachers and safe learning spaces.\n\nRemoving one barrier creates room for the next hopeful step: another lesson, another term, and another chance to imagine what comes next.","imageAlt":"A teacher supporting students in a classroom","buttonText":"Read more","authorName":"ShareHope Education Team","seoTitle":"Small barriers can make a big difference | ShareHope","seoDescription":"Understand how practical education support can help a student stay in school.","tags":["Education","Opportunity"]}}'::jsonb, updated_at = NOW() WHERE slug = 'amina-student-to-teacher';

UPDATE blog_posts SET slug = 'measuring-progress-with-dignity', translations = '{"en":{"title":"Measuring progress with dignity","excerpt":"Numbers matter, but community feedback helps us understand whether a program is useful, respectful, and creating the kind of change people actually value.","body":"Good reporting should show where resources went and what they helped accomplish. It should also make space for the experience of the people a program is intended to serve.\n\nShareHope considers participation, access, and practical outcomes while listening closely to community feedback.\n\nAccountability is not only about counting activity. It is about learning, adjusting, and honoring the dignity of every person represented by the numbers.","imageAlt":"Community members sharing feedback in conversation","buttonText":"Read more","authorName":"ShareHope Editorial Team","seoTitle":"Measuring progress with dignity | ShareHope","seoDescription":"Learn why community feedback is essential to meaningful and accountable impact reporting.","tags":["Field Notes","Impact"]}}'::jsonb, updated_at = NOW() WHERE slug = 'measuring-dignity';
